-- Dev and local test data only (never run on live): the old RAMS builder's built-in hazard list
-- (legacy/pages/cbs-rams-builder.html, HAZARD_LIB) and two fake CoSHH substances. The live import at
-- switch-over merges live's hazard register with this list and lists near-duplicates for Ethan to choose.
insert into hazards (hazard, harm, controls, likelihood, consequence, residual_likelihood, residual_consequence, rams_key, source, review_on, created_by) values
  ('Working on client sites', 'All staff and contractors: injury or ill health from lack of awareness on an unfamiliar site.', 'All employees receive the site induction. Controlled entry to authorised persons only. RAMS read and understood and signed by all operatives. Site warning and information signs displayed. Toolbox talks and site safety briefings given.', 3, 3, 1, 3, 'client_site', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Vehicle, FLT and site traffic movement', 'All staff and others: injury caused by collision with FLTs, HGVs and site vehicles.', 'Hi-vis worn at all times. Segregated vehicle and pedestrian routes and pedestrian walkways used. Traffic barriers deployed. Vehicle and plant movements carried out with a banksman. Barriers in place to prevent unauthorised access. Aisles and gangways kept clear.', 4, 5, 1, 4, 'flt', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Slips, trips and falls (people movement)', 'All staff: injury from slips, trips and falls on wet floors, spillages, cables and poor housekeeping.', 'Areas kept clear to prevent slips, trips and falls. Good housekeeping observed during the task with daily inspections. Spillages cleaned up immediately; wet floor signs and spill kits available. Safety footwear to BS EN ISO 20345 worn. Waste disposed of in skips.', 3, 3, 1, 2, 'slips', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Access/egress obstructions and trailing cables', 'All staff: slips, trips and falls from obstructions and trailing leads.', 'Delivery and work areas kept clear of obstructions. Equipment sited so as not to obstruct routes when in use. Pedestrians segregated. Trailing cables avoided or routed overhead / covered.', 3, 3, 1, 2, 'access', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Manual handling', 'All staff: sprains, strains and musculoskeletal injury from lifting, carrying and repetitive handling.', 'Avoid unnecessary manual handling. Mechanical aids, trolleys and pallet trucks provided and used. Loads split; team lifts used. Manual handling training and good technique. Manual handling risk assessment for heavy or awkward items. Foot protection worn.', 4, 3, 1, 3, 'manual', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Hand tools', 'All staff: cuts and impact injuries while using hand tools.', 'Only competent persons use the equipment. Employees trained in the correct use of tools. Tools kept in good condition, cleaned, checked and stored after use, and carried correctly. Gloves to EN 388 (cut resistant) and eye protection worn.', 3, 2, 1, 2, 'hand_tools', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Electrical equipment and power tools', 'All staff: electric shock, burns and injury from damaged or misused power tools.', 'Battery or 110v tools only. Pre-use checks by the user; regular PAT testing. Only competent, trained persons operate equipment. Routine maintenance and safety checks undertaken. Defective equipment taken out of use.', 3, 5, 1, 4, 'electrical', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Dust', 'All staff and others nearby: respiratory ill health from inhaling harmful dust.', 'On-tool extraction and M/H-class vacuums; shadow vacuuming; water suppression where possible. Protective screens or enclosure. RPE (FFP3) worn and face-fit tested. Good housekeeping and hygiene. Area kept clear of other staff.', 4, 4, 1, 3, 'dust', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Brick, concrete and silica dust (RCS)', 'All staff: serious lung disease (silicosis) from respirable crystalline silica when cutting, grinding or breaking concrete, brick and stone.', 'Wet cutting or on-tool extraction on every cut. FFP3 respirator worn. Exposure time limited. Dry sweeping not permitted; vacuum clean.', 4, 5, 1, 3, 'silica', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Noise at or above 85 dB(A)', 'All staff: hearing damage from excessive noise.', 'Noise assessed and tools selected for lower noise. Hearing protection provided and worn; hearing protection zones designated. Exposure time limited.', 4, 3, 1, 2, 'noise', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Hand arm vibration', 'Operatives: hand-arm vibration syndrome from breakers, grinders, saws and compaction plant.', 'Low-vibration equipment selected. Trigger time recorded and kept below the exposure action value. Job rotation. HAV training given; operatives self-check for symptoms and report.', 4, 3, 1, 3, 'havs', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Work equipment (wacker plate / compaction)', 'Operatives: injury from misuse or poorly maintained compaction plant.', 'Instruction manual read and understood. Only competent persons operate the equipment. Written safe system of work. Routine maintenance undertaken.', 3, 3, 1, 2, 'wacker', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Rotating and moving abrasive grinding wheel', 'Operatives: injury from contact with the wheel, disc burst, ejected debris and dust.', 'Guards checked before use. Only competent (abrasive wheel trained) persons operate. Eye and face protection, EN 388 gloves and hearing protection worn. On-tool extraction. 110v or battery tools.', 4, 4, 1, 3, 'grinder', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Wet cement, concrete and mortar', 'All staff: skin burns, dermatitis and eye injury from contact with wet cement products.', 'COSHH assessments communicated. Gloves to EN 374, eye protection and foot protection worn. Barrier cream and hygiene / wash station provided; regular skin checks. Spillage prevented from entering drains.', 4, 3, 1, 2, 'wet_concrete', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Use of resin', 'All staff: respiratory irritation from fumes and dermatitis from skin contact with resins.', 'COSHH assessment communicated and SDS on site. Area kept clear of non-essential persons while resin is applied and curing. Chemical-resistant gloves and safety glasses worn. Good ventilation.', 4, 3, 1, 2, 'resin', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Paint, fillers and decorating materials', 'All staff: dermatitis, eye irritation and inhalation of solvents and VOCs.', 'COSHH assessments communicated; employees trained in COSHH. Gloves (EN 455 / EN 374) and eye protection worn; eye wash available. Natural ventilation. Containers labelled and stored correctly. Good hand washing; no solvents used to clean hands.', 3, 3, 1, 2, 'paint', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Chemicals and hazardous substances', 'All staff: injury or ill health from uncontrolled hazardous substances.', 'COSHH assessments communicated. Chemicals correctly labelled and stored securely with lids on; flammables stored securely. Workers trained in COSHH. Appropriate gloves worn.', 3, 3, 1, 2, 'chemicals', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Fire and flammable materials', 'All persons: injury from fire and smoke inhalation.', 'No naked flames or hot works without a permit. No smoking. Flammable materials stored correctly and containers labelled. All persons aware of the fire procedures from induction. Fire exits and signage kept clear. Extinguishers provided in higher-risk areas.', 3, 5, 1, 4, 'fire', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Working at height', 'All staff: serious injury from falls from height and falling objects.', 'Work at height planned and avoided where possible. Suitable access equipment (podium, tower, MEWP) used by trained operatives; edge protection where needed. Exclusion zone below. Equipment inspected before use.', 4, 5, 1, 4, 'height', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Ladders and stepladders', 'All staff: injury from falling from ladders or stepladders.', 'Correct type of ladder used; visually inspected before each use; defective ladders removed from use. Used on firm level ground for short-duration light work only, three points of contact. Employees trained in ladder use. Not used in extreme weather.', 4, 4, 1, 3, 'ladders', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Falling objects', 'Staff and others below: injury from tools, materials or debris falling from height.', 'Exclusion zone below overhead work. Tools and materials kept secure at height. Hard hats worn in the work area.', 3, 4, 1, 3, 'falling', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Poor lighting', 'All staff: injury from not being able to see hazards clearly.', 'Adequate lighting maintained at all times. Additional internal and external task lighting provided where needed.', 3, 3, 1, 2, 'lighting', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Buried services', 'Operatives: electric shock, burns or gas release from striking buried services.', 'Service drawings obtained and permit to dig issued. Area scanned (CAT and Genny) before breaking ground. Hand dig near pipes and cables. Emergency procedure for a struck service; any damage reported immediately.', 4, 5, 1, 4, 'buried', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Unprotected excavations', 'All persons: injury from falling into open excavations.', 'Excavations barriered and signed; no pedestrian access. Guard rails provided where needed. Excavations covered or backfilled before leaving site.', 3, 4, 1, 2, 'excavation', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Adverse weather', 'Operatives: injury from high winds, heavy rain, snow, ice and lightning.', 'Weather forecast checked and work planned for it. Work postponed in adverse conditions. Protective clothing and footwear worn.', 3, 3, 1, 2, 'adverse_weather', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Lone working', 'Lone workers: delayed help after an accident or illness.', 'Lone working procedure followed. Mobile phone carried and check-in calls with the office. Higher-risk tasks not carried out alone.', 3, 4, 1, 3, 'lone', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)'),
  ('Waste removal', 'All staff: injury or ill health while handling and removing waste.', 'Waste bagged to manageable weights and taken to skips as work proceeds. Gloves worn. Hazardous waste segregated and removed by CBS.', 3, 2, 1, 2, 'waste', 'RAMS builder list', (current_date + interval '1 year')::date, 'seed (dev test data)')
on conflict do nothing;

-- Control types per hazard (the builder's CT_HAZ list, same order).
update hazards set control_codes = array['I', 'A']::text[] where rams_key = 'client_site' and control_codes = '{}';
update hazards set control_codes = array['I', 'G', 'A', 'P']::text[] where rams_key = 'flt' and control_codes = '{}';
update hazards set control_codes = array['G', 'A', 'P']::text[] where rams_key = 'slips' and control_codes = '{}';
update hazards set control_codes = array['G', 'A']::text[] where rams_key = 'access' and control_codes = '{}';
update hazards set control_codes = array['G', 'A', 'P']::text[] where rams_key = 'manual' and control_codes = '{}';
update hazards set control_codes = array['A', 'P']::text[] where rams_key = 'hand_tools' and control_codes = '{}';
