update hazards set control_codes = array['G', 'A', 'P']::text[] where rams_key = 'grinder' and control_codes = '{}';
update hazards set control_codes = array['G', 'A', 'P']::text[] where rams_key = 'wet_concrete' and control_codes = '{}';
update hazards set control_codes = array['I', 'A', 'P']::text[] where rams_key = 'resin' and control_codes = '{}';
update hazards set control_codes = array['S', 'G', 'A', 'P']::text[] where rams_key = 'paint' and control_codes = '{}';
update hazards set control_codes = array['S', 'A', 'P']::text[] where rams_key = 'chemicals' and control_codes = '{}';
update hazards set control_codes = array['E', 'I', 'A']::text[] where rams_key = 'fire' and control_codes = '{}';
