update hazards set control_codes = array['I', 'G', 'A']::text[] where rams_key = 'buried' and control_codes = '{}';
update hazards set control_codes = array['I', 'G', 'A']::text[] where rams_key = 'excavation' and control_codes = '{}';
update hazards set control_codes = array['E', 'A', 'P']::text[] where rams_key = 'adverse_weather' and control_codes = '{}';
