insert into suppliers (name, created_by) values ('ZZ Fake Paint Supplies', 'seed (dev test data)') on conflict do nothing;
insert into substances (product, supplier_id, use_for, ghs, controls, status, created_by)
select 'ZZ Fake White Spirit', id, 'Cleaning brushes', array['flammable', 'harmful', 'health'], 'Use in a ventilated area. No naked flames.', 'draft', 'seed (dev test data)'
from suppliers where name = 'ZZ Fake Paint Supplies' on conflict do nothing;
insert into substances (product, supplier_id, use_for, ghs, controls, status, created_by)
select 'ZZ Fake Cement', id, 'Mixing mortar', array['corrosive', 'harmful'], 'Gloves and eye protection. Wash skin straight away.', 'draft', 'seed (dev test data)'
from suppliers where name = 'ZZ Fake Paint Supplies' on conflict do nothing;
